CREATE TRIGGER RefCusTariffRelationship_Combined
	ON RefCusTariffRelationship
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZZH_DataSetPK = inserted.ZZH_ZZ1_Tariff,
		ZZH_DataSetCode = 'ZZ1'
		FROM RefCusTariffRelationship t
		JOIN inserted ON t.ZZH_PK = inserted.ZZH_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZZH_DataSetPK, t.ZZH_DataSetCode
	FROM RefCusTariffRelationship t
	JOIN inserted ON t.ZZH_PK = inserted.ZZH_PK
	UNION
	SELECT ZZH_DataSetPK, ZZH_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusTariffRelationship_DataProcessingResult_Delete
	ON RefCusTariffRelationship
